<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>SnapFrame — Capture, Create & Share What You Love</title>
<meta name="description" content="SnapFrame is a social media platform that makes it easy to capture, create, and share what you love with the people who matter most.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Fredoka:wght@400;500;600;700&family=Nunito:wght@300;400;500;600;700&display=swap" rel="stylesheet">
<style>
/* ── Reset & Base ── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; }
body {
  font-family: 'Nunito', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  font-size: 16px;
  line-height: 1.6;
  color: #1E293B;
  background: #FFFFFF;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}
img { display: block; max-width: 100%; }
a { color: inherit; text-decoration: none; }
button { font: inherit; cursor: pointer; border: none; background: none; }
ul, ol { list-style: none; }

/* ── Typography ── */
h1, h2, h3, h4 { font-family: 'Fredoka', sans-serif; }
h1 { font-size: clamp(2.25rem, 5vw, 4rem); font-weight: 700; line-height: 1.15; }
h2 { font-size: clamp(1.75rem, 3.5vw, 2.75rem); font-weight: 600; line-height: 1.25; }
h3 { font-size: clamp(1.25rem, 2.5vw, 1.75rem); font-weight: 600; line-height: 1.3; }

/* ── Utility ── */
.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); border: 0; }

/* ── Buttons ── */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  padding: 14px 32px; border-radius: 50px; font-weight: 600; font-size: 1rem;
  transition: all 200ms ease; white-space: nowrap;
}
.btn-primary { background: #7638FA; color: #fff; }
.btn-primary:hover { background: #5f20e0; transform: translateY(-1px); box-shadow: 0 8px 24px rgba(118,56,250,0.35); }
.btn-dark { background: #000; color: #fff; }
.btn-dark:hover { background: #1E293B; transform: translateY(-1px); box-shadow: 0 8px 24px rgba(0,0,0,0.25); }
.btn-outline { border: 2px solid #E2E8F0; color: #1E293B; background: #fff; }
.btn-outline:hover { border-color: #7638FA; color: #7638FA; }
.btn-lg { padding: 18px 40px; font-size: 1.125rem; }

/* ── Header ── */
.header {
  position: fixed; top: 0; left: 0; right: 0; z-index: 1000;
  background: rgba(255,255,255,0.92); backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(0,0,0,0.06);
  transition: background 200ms ease;
}
.header-inner {
  display: flex; align-items: center; justify-content: space-between;
  height: 72px; max-width: 1280px; margin: 0 auto; padding: 0 24px;
}
.header-logo {
  font-family: 'Fredoka', sans-serif; font-size: 1.75rem; font-weight: 700;
  color: #000; letter-spacing: -0.5px;
}
.header-logo span { color: #7638FA; }
.header-nav { display: flex; align-items: center; gap: 32px; }
.header-nav a {
  font-weight: 500; font-size: 0.95rem; color: #475569;
  transition: color 150ms ease; padding: 4px 0; border-bottom: 2px solid transparent;
}
.header-nav a:hover { color: #7638FA; }
.header-actions { display: flex; align-items: center; gap: 12px; }

/* ── Hamburger ── */
.hamburger { display: none; flex-direction: column; justify-content: center; gap: 5px;
  width: 44px; height: 44px; padding: 10px; border-radius: 8px; z-index: 1100;
  transition: background 150ms;
}
.hamburger:hover { background: #F1F5F9; }
.hamburger span {
  display: block; width: 24px; height: 2.5px; border-radius: 2px;
  background: #1E293B; transition: all 250ms ease; transform-origin: center;
}
.hamburger.active span:nth-child(1) { transform: translateY(7.5px) rotate(45deg); }
.hamburger.active span:nth-child(2) { opacity: 0; transform: scaleX(0); }
.hamburger.active span:nth-child(3) { transform: translateY(-7.5px) rotate(-45deg); }

.mobile-nav {
  display: none; position: fixed; inset: 0; z-index: 1050;
  background: rgba(255,255,255,0.98); backdrop-filter: blur(16px);
  flex-direction: column; align-items: center; justify-content: center; gap: 32px;
  opacity: 0; pointer-events: none; transition: opacity 300ms ease;
}
.mobile-nav.open { opacity: 1; pointer-events: auto; }
.mobile-nav a {
  font-family: 'Fredoka', sans-serif; font-size: 1.5rem; font-weight: 600;
  color: #1E293B; transition: color 150ms;
}
.mobile-nav a:hover { color: #7638FA; }

/* ── Hero ── */
.hero {
  position: relative; min-height: 100vh; display: flex; align-items: center;
  padding: 120px 0 80px; overflow: hidden; background: #FAFBFC;
}
.hero::before {
  content: ''; position: absolute; top: -50%; right: -20%; width: 800px; height: 800px;
  border-radius: 50%; background: radial-gradient(circle, rgba(118,56,250,0.12) 0%, transparent 70%);
  pointer-events: none;
}
.hero::after {
  content: ''; position: absolute; bottom: -30%; left: -15%; width: 600px; height: 600px;
  border-radius: 50%; background: radial-gradient(circle, rgba(255,122,0,0.10) 0%, transparent 70%);
  pointer-events: none;
}
.hero-content { position: relative; z-index: 1; max-width: 720px; }
.hero-content h1 { margin-bottom: 24px; }
.hero-content h1 span { background: linear-gradient(135deg, #7638FA 0%, #FF7A00 100%); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text; }
.hero-subtitle { font-size: clamp(1.1rem, 2vw, 1.35rem); color: #475569; margin-bottom: 40px; max-width: 560px; line-height: 1.7; }
.hero-visual {
  position: absolute; right: -40px; top: 50%; transform: translateY(-50%);
  width: 500px; height: 500px; z-index: 0;
  background: linear-gradient(135deg, #7638FA 0%, #FF7A00 50%, #7638FA 100%);
  border-radius: 50%; opacity: 0.06; pointer-events: none;
}

/* ── Sections ── */
.section { padding: 100px 0; }
.section-label {
  display: inline-block; font-size: 0.85rem; font-weight: 700; letter-spacing: 0.05em;
  text-transform: uppercase; color: #7638FA; margin-bottom: 16px;
}
.section-heading { margin-bottom: 20px; }
.section-description { font-size: 1.15rem; color: #475569; max-width: 600px; line-height: 1.7; margin-bottom: 32px; }

/* ── Features ── */
.features { background: #fff; }
.features-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 24px; margin-top: 48px; }
.feature-card {
  background: #F8FAFC; border-radius: 20px; padding: 32px;
  border: 1px solid #E2E8F0; transition: all 250ms ease;
}
.feature-card:hover { transform: translateY(-4px); box-shadow: 0 12px 40px rgba(0,0,0,0.08); border-color: #CBD5E1; }
.feature-icon {
  width: 56px; height: 56px; border-radius: 16px; display: flex; align-items: center;
  justify-content: center; margin-bottom: 20px; font-size: 1.5rem;
}
.feature-icon.clips { background: linear-gradient(135deg, #7638FA, #5f20e0); }
.feature-icon.stories { background: linear-gradient(135deg, #FF7A00, #e06a00); }
.feature-icon.dms { background: linear-gradient(135deg, #7638FA, #a855f7); }
.feature-icon.explore { background: linear-gradient(135deg, #FF7A00, #f59e0b); }
.feature-card h3 { margin-bottom: 8px; }
.feature-card p { color: #64748B; line-height: 1.6; }

/* ── Safety ── */
.safety { background: #FDFBFF; position: relative; overflow: hidden; }
.safety::before {
  content: ''; position: absolute; top: 10%; right: -5%; width: 400px; height: 400px;
  border-radius: 50%; background: radial-gradient(circle, rgba(118,56,250,0.06) 0%, transparent 70%);
  pointer-events: none;
}
.safety-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 20px; margin-top: 40px; }
.safety-card {
  background: #fff; border-radius: 16px; padding: 28px;
  border: 1px solid #E2E8F0; transition: all 200ms ease;
}
.safety-card:hover { box-shadow: 0 4px 20px rgba(0,0,0,0.05); border-color: #CBD5E1; }
.safety-card-icon { font-size: 1.5rem; margin-bottom: 12px; }
.safety-card h4 { margin-bottom: 6px; font-size: 1.05rem; }
.safety-card p { color: #64748B; font-size: 0.95rem; line-height: 1.6; }

/* ── Creators ── */
.creators { background: #FFFBF5; position: relative; overflow: hidden; }
.creators::before {
  content: ''; position: absolute; bottom: 10%; left: -5%; width: 400px; height: 400px;
  border-radius: 50%; background: radial-gradient(circle, rgba(255,122,0,0.08) 0%, transparent 70%);
  pointer-events: none;
}
.creators-stats { display: flex; gap: 48px; margin-top: 40px; flex-wrap: wrap; }
.creators-stat { text-align: center; }
.creators-stat-number { font-family: 'Fredoka', sans-serif; font-size: 2.5rem; font-weight: 700; color: #000; }
.creators-stat-label { font-size: 0.95rem; color: #64748B; margin-top: 4px; }

/* ── Tagline Banner ── */
.tagline-banner {
  background: linear-gradient(135deg, #7638FA 0%, #5f20e0 50%, #FF7A00 100%);
  padding: 80px 0; text-align: center; position: relative; overflow: hidden;
}
.tagline-banner::before {
  content: ''; position: absolute; inset: 0;
  background: radial-gradient(circle at 30% 50%, rgba(255,255,255,0.1) 0%, transparent 60%);
  pointer-events: none;
}
.tagline-banner h2 {
  color: #fff; font-size: clamp(2rem, 4.5vw, 3.25rem); font-weight: 600; position: relative; z-index: 1;
}

/* ── News Carousel ── */
.news { background: #fff; }
.news-header { display: flex; align-items: flex-end; justify-content: space-between; margin-bottom: 32px; flex-wrap: wrap; gap: 16px; }
.carousel-wrapper { position: relative; }
.carousel {
  display: flex; gap: 20px; overflow-x: auto; scroll-snap-type: x mandatory;
  scroll-behavior: smooth; -webkit-overflow-scrolling: touch;
  padding-bottom: 8px; -ms-overflow-style: none; scrollbar-width: none;
}
.carousel::-webkit-scrollbar { display: none; }
.carousel-card {
  flex: 0 0 340px; scroll-snap-align: start; border-radius: 20px;
  background: #F8FAFC; border: 1px solid #E2E8F0; overflow: hidden;
  transition: all 250ms ease; cursor: pointer;
}
.carousel-card:hover { transform: translateY(-4px); box-shadow: 0 12px 40px rgba(0,0,0,0.1); }
.carousel-card-thumb {
  width: 100%; height: 200px; display: flex; align-items: center; justify-content: center;
  font-size: 3rem; color: #fff; position: relative; overflow: hidden;
}
.carousel-card:nth-child(1) .carousel-card-thumb { background: linear-gradient(135deg, #7638FA, #5B21B6); }
.carousel-card:nth-child(2) .carousel-card-thumb { background: linear-gradient(135deg, #FF7A00, #C2410C); }
.carousel-card:nth-child(3) .carousel-card-thumb { background: linear-gradient(135deg, #2563EB, #1D4ED8); }
.carousel-card:nth-child(4) .carousel-card-thumb { background: linear-gradient(135deg, #7C3AED, #5B21B6); }
.carousel-card-body { padding: 20px; }
.carousel-card-tags { display: flex; gap: 6px; flex-wrap: wrap; margin-bottom: 12px; }
.carousel-card-tag {
  display: inline-block; font-size: 0.7rem; font-weight: 700;
  padding: 4px 10px; border-radius: 50px; letter-spacing: 0.03em;
}
.tag-announcements { background: #EDE9FE; color: #7638FA; }
.tag-tips { background: #FFF7ED; color: #FF7A00; }
.tag-product { background: #EFF6FF; color: #2563EB; }
.tag-safety { background: #ECFDF5; color: #059669; }
.carousel-card-title { font-size: 1rem; font-weight: 700; line-height: 1.4; margin-bottom: 8px; color: #1E293B; }
.carousel-card-date { font-size: 0.85rem; color: #94A3B8; }
.carousel-arrows { display: flex; gap: 8px; margin-top: 20px; }
.carousel-arrow {
  width: 44px; height: 44px; border-radius: 50%; display: flex; align-items: center;
  justify-content: center; background: #F1F5F9; border: 1px solid #E2E8F0;
  transition: all 150ms ease; font-size: 1.1rem; color: #1E293B;
}
.carousel-arrow:hover { background: #7638FA; color: #fff; border-color: #7638FA; }

/* ── CTA Download ── */
.cta-download {
  background: linear-gradient(135deg, #000 0%, #1E293B 100%);
  padding: 100px 0; text-align: center; position: relative; overflow: hidden;
}
.cta-download::before {
  content: ''; position: absolute; top: -50%; left: 50%; transform: translateX(-50%);
  width: 600px; height: 600px; border-radius: 50%;
  background: radial-gradient(circle, rgba(118,56,250,0.15) 0%, transparent 70%);
  pointer-events: none;
}
.cta-download h2 { color: #fff; margin-bottom: 12px; }
.cta-download p { color: #94A3B8; font-size: 1.15rem; margin-bottom: 40px; }
.cta-buttons { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; position: relative; z-index: 1; }
.cta-store-btn {
  display: inline-flex; align-items: center; gap: 10px; padding: 14px 28px;
  border-radius: 50px; font-weight: 600; font-size: 0.95rem; border: 2px solid rgba(255,255,255,0.2);
  color: #fff; transition: all 200ms ease;
}
.cta-store-btn:hover { background: rgba(255,255,255,0.1); border-color: rgba(255,255,255,0.4); }
.cta-store-btn svg { flex-shrink: 0; }

/* ── Footer ── */
.footer { background: #F8FAFC; border-top: 1px solid #E2E8F0; padding: 80px 0 40px; }
.footer-grid { display: grid; grid-template-columns: repeat(6, 1fr); gap: 32px; }
.footer-col h4 { font-size: 0.85rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.04em; color: #1E293B; margin-bottom: 16px; }
.footer-col ul { display: flex; flex-direction: column; gap: 10px; }
.footer-col a { font-size: 0.9rem; color: #64748B; transition: color 150ms; }
.footer-col a:hover { color: #7638FA; }
.footer-bottom { margin-top: 64px; padding-top: 32px; border-top: 1px solid #E2E8F0; }
.footer-bottom-row { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 24px; }
.footer-language {
  display: flex; align-items: center; gap: 8px; font-size: 0.9rem; color: #64748B;
  padding: 8px 16px; border: 1px solid #E2E8F0; border-radius: 8px; cursor: pointer;
  transition: border-color 150ms;
}
.footer-language:hover { border-color: #CBD5E1; }
.footer-social { display: flex; gap: 16px; }
.footer-social a {
  width: 40px; height: 40px; border-radius: 50%; display: flex; align-items: center;
  justify-content: center; background: #E2E8F0; color: #475569;
  transition: all 150ms ease; font-size: 0.85rem; font-weight: 600;
}
.footer-social a:hover { background: #7638FA; color: #fff; }
.footer-legal { display: flex; gap: 20px; flex-wrap: wrap; }
.footer-legal a { font-size: 0.85rem; color: #94A3B8; transition: color 150ms; }
.footer-legal a:hover { color: #1E293B; }

/* ── Responsive ── */
@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .hero-visual { width: 350px; height: 350px; right: -80px; }
}
