<script>
// ── Hamburger Menu ──
(function() {
  const hamburger = document.querySelector('.hamburger');
  const mobileNav = document.getElementById('mobileNav');
  let menuOpen = false;

  function openMenu() {
    menuOpen = true;
    hamburger.classList.add('active');
    hamburger.setAttribute('aria-expanded', 'true');
    mobileNav.classList.add('open');
    mobileNav.setAttribute('aria-hidden', 'false');
    document.body.style.overflow = 'hidden';
  }

  function closeMenu() {
    menuOpen = false;
    hamburger.classList.remove('active');
    hamburger.setAttribute('aria-expanded', 'false');
    mobileNav.classList.remove('open');
    mobileNav.setAttribute('aria-hidden', 'true');
    document.body.style.overflow = '';
  }

  hamburger.addEventListener('click', function() {
    menuOpen ? closeMenu() : openMenu();
  });

  // Close menu when a nav link is clicked
  mobileNav.querySelectorAll('a, button').forEach(function(el) {
    el.addEventListener('click', closeMenu);
  });

  // Close on Escape key
  document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape' && menuOpen) closeMenu();
  });
})();

// ── News Carousel ──
(function() {
  var carousel = document.getElementById('newsCarousel');
  var prevBtn = document.getElementById('carouselPrev');
  var nextBtn = document.getElementById('carouselNext');
  if (!carousel) return;

  var scrollAmount = 360; // card width + gap

  function updateArrowVisibility() {
    if (!prevBtn || !nextBtn) return;
    var tolerance = 4;
    var atStart = carousel.scrollLeft <= tolerance;
    var atEnd = carousel.scrollLeft + carousel.clientWidth >= carousel.scrollWidth - tolerance;
    prevBtn.style.opacity = atStart ? '0.4' : '1';
    prevBtn.style.pointerEvents = atStart ? 'none' : 'auto';
    nextBtn.style.opacity = atEnd ? '0.4' : '1';
    nextBtn.style.pointerEvents = atEnd ? 'none' : 'auto';
  }

  if (prevBtn) {
    prevBtn.addEventListener('click', function() {
      carousel.scrollBy({ left: -scrollAmount, behavior: 'smooth' });
    });
  }
  if (nextBtn) {
    nextBtn.addEventListener('click', function() {
      carousel.scrollBy({ left: scrollAmount, behavior: 'smooth' });
    });
  }
